def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product of a number obtained by inserting K multiplication signs into a number string.

    :param num_str: A string representing the number string.
    :param N: An integer representing the length of the number string.
    :param K: An integer representing the number of multiplication signs to insert.
    :return: The maximum product of the resulting number.
    """
    if not num_str or N == 0 or K < 0:
        return 0

    from functools import lru_cache

    @lru_cache(None)
    def dp(index, multipliers):
        if index == N:
            return 1 if multipliers == 0 else 0

        if multipliers < 0:
            return 0

        max_val = 0
        num_chars = 0

        for i in range(index, N):
            num_chars = num_chars * 10 + int(num_str[i])
            if multipliers > 0:
                max_val = max(max_val, num_chars * dp(i + 1, multipliers - 1))
            else:
                max_val = max(max_val, num_chars)

        return max_val

    return dp(0, K)

