    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: A string that represents the polynomial.
    """
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue

        if i == 0:
            term = f"{coeff}"
        elif i == 1:
            term = f"{coeff}x" if coeff != 1 else "x"
        else:
            term = f"{coeff}x^{i}" if coeff != 1 else f"x^{i}"

        if term[0] == '+':
            term = term[1:]

        terms.append(term)

    polynomial = '-'.join(terms).replace('-+', '-')
    return polynomial

