def generate_numbers(n, rules) -> int:
    from collections import deque

    # Initialize a set to store unique numbers
    unique_numbers = set()

    # Initialize a queue for BFS
    queue = deque([n])

    # While there are more numbers to process in the queue
    while queue:
        num = queue.popleft()
        if num not in unique_numbers:
            unique_numbers.add(num)

            # Generate all possible transformations for the current number
            num_str = str(num)
            for i in range(len(num_str)):
                for x, y in rules:
                    if int(num_str[i]) == x:
                        transformed_num = int(num_str[:i] + str(y) + num_str[i+1:])
                        queue.append(transformed_num)

    # Return the count of unique numbers generated
    return len(unique_numbers)

