                elif " is not guilty" in statement and statement.replace(" is not guilty", " is guilty") not in participant_statements:
                    return False
            else:
                # Truth-teller always tells the truth
                if " is guilty" in statement and participant != scenario:
                    return False
                elif " is not guilty" in statement and participant == scenario:
                    return False

    return True

