def calculate_score(system: int, points: str) -> list:
    if system not in [11, 21]:
        raise ValueError("Invalid scoring system. Must be either 11 or 21 points.")

    game_scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        if player_score >= system and player_score - opponent_score >= 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0
        elif opponent_score >= system and opponent_score - player_score >= 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

