def calculate_arrangements(n: int, m: int, a: List[int]) -> int:
    MOD = 10**6 + 7

    # Calculate the number of ways to arrange m pots of flowers using up to n types
    # where each type can have at most a[i] pots and the arrangement must be in
    # increasing order of flower types.

    # Initialize the result
    result = 0

    # Iterate over all possible numbers of pots for the first flower type
    for i in range(m + 1):
        if i > a[0]:
            break
        # Iterate over all possible numbers of pots for the second flower type
        for j in range(i, m + 1):
            if j > a[1]:
                break
            # Iterate over all possible numbers of pots for the third flower type
            for k in range(j, m + 1):
                if k > a[2]:
                    break
                # Check if the total number of pots used is equal to m
                if i + j + k == m:
                    # Calculate the number of ways to arrange the pots
                    result = (result + comb(m, i) * comb(m - i, j) * comb(m - i - j, k)) % MOD

    return result

