    max_increasing_subseq = [1] * n
    max_decreasing_subseq = [1] * n

    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            max_increasing_subseq[i] = max_increasing_subseq[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            max_decreasing_subseq[i] = max_decreasing_subseq[i + 1] + 1

    min_students_to_leave = float('inf')
    for i in range(1, n - 1):
        min_students_to_leave = min(min_students_to_leave, 
                                     n - (max_increasing_subseq[i - 1] + max_decreasing_subseq[i]))

    return min_students_to_leave

def minimum_students_to_leave(heights):
    n = len(heights)
    if n < 3:
        return 0

    min_to_leave = n

    for i in range(1, n - 1):
        left_increasing = all(heights[j] <= heights[j + 1] for j in range(i))
        right_decreasing = all(heights[j] >= heights[j + 1] for j in range(i, n - 1))
        if left_increasing and right_decreasing:
            min_to_leave = min(min_to_leave, n - (i + 1))

    return min_to_leave

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Initialize the left and right arrays to store the maximum increasing and decreasing subsequences length
    left = [1] * n
    right = [1] * n

    # Calculate the maximum increasing subsequence length ending at each position
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left[i] = left[i - 1] + 1

    # Calculate the maximum decreasing subsequence length starting at each position
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right[i] = right[i + 1] + 1

    # Calculate the maximum length of the choir formation
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, left[i] + right[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir length
    return n - max_choir_length

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be at least 1.")
    moves = 2 ** (2 * n) - 2
    return moves
